            <th>Open</th>
            <th>Active</th>
            <th>Aged 0-30</th>
            <th>Aged 31-60</th>
            <th>Aged 61+</th>
            {periods.map((period) => (
              <th key={period.name}>Due {period.name}</th>
            ))}
            <th>Cut</th>
            <th>Patrons</th>
